/**
 * Build a WhatsApp-safe form-link message.
 * Splits around {{form_link}} so the bare URL can be sent alone (avoids WhatsApp
 * soft-hyphenating long URLs mid-line). Prefer: intro → link → optional footer.
 */
function buildFormLinkParts(template, vars = {}) {
  const link = sanitizeFormLink(vars.form_link);
  const marker = '___FORM_LINK___';
  const rendered = renderTemplate(String(template || ''), {
    ...vars,
    form_link: marker,
  }).replace(/[\u00AD\u200B-\u200D\uFEFF]/g, '');

  const idx = rendered.indexOf(marker);
  let intro;
  let footer = '';

  if (idx === -1) {
    intro = rendered.replace(/\n{3,}/g, '\n\n').trim() || 'Please fill out this short form:';
  } else {
    intro = rendered
      .slice(0, idx)
      .replace(/[ \t]+\n/g, '\n')
      .replace(/\n{3,}/g, '\n\n')
      .trim();
    footer = rendered
      .slice(idx + marker.length)
      .replace(/[ \t]+\n/g, '\n')
      .replace(/\n{3,}/g, '\n\n')
      .trim();
    if (!intro) intro = 'Please fill out this short form:';
  }

  const combined = [intro, link, footer].filter(Boolean).join('\n\n');
  return { intro, link, footer, combined };
}

old_string:
/**
 * Build a WhatsApp-safe form-link message.
 * Puts the bare URL on its own line (blank lines around it) so WhatsApp does not
 * soft-hyphenate / wrap mid-URL next to surrounding text.
 *
 * Returns { intro, link, combined } — prefer sending intro then link as two messages.
 */
function buildFormLinkParts(template, vars = {}) {
  const link = sanitizeFormLink(vars.form_link);
  const marker = '___FORM_LINK___';
  const rendered = renderTemplate(String(template || ''), {
    ...vars,
    form_link: marker,
  });

  let intro = rendered
    .replace(new RegExp(`\\s*${marker}\\s*`, 'g'), '\n\n')
    .replace(/[\u00AD\u200B-\u200D\uFEFF]/g, '')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/[:：]\s*$/m, ':')
    .trim();

  if (!intro) {
    intro = 'Please fill out this short form:';
  }

  const combined = link
    ? `${intro}\n\n${link}\n`.replace(/\n{3,}/g, '\n\n').trim()
    : intro;

  return { intro, link, combined };
}
